// Built-in copies of click.wav, don.wav and ka.wav (base64).
// They let the site play its sounds even when the .wav files can't be fetched,
// e.g. when index.html is opened straight from disk (file://).
window.BUILTIN_SOUNDS = {
  click: "data:audio/wav;base64,",
  hit: "data:audio/wav;base64,",
  accent: "data:audio/wav;base64,",
};
